INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (13, 21, 'theory', 'Quiz: descriptors, property and slots');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 0, 'What is a descriptor?', '["A decorator for functions", "An attribute with a double underscore", "An object in a class attribute with __get__, __set__ or __delete__", "The dictionary of an instance''s attributes"]', 2, 'A descriptor gets control when the attribute is accessed through an instance; property, methods and slots are ready-made descriptors.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 1, 'Where does self come from when you call obj.method()?', '["A function in a class is a descriptor: its __get__ returns a bound method with obj remembered", "Python copies the object", "self is a reserved word", "Every method keeps a reference to the instance from birth"]', 0, 'Through an instance, function.__get__ creates a bound method and passes obj as the first argument; through the class it returns the function as is.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 2, 'Where should the value checked by a data descriptor be stored?', '["In the descriptor itself", "In a global dictionary", "In a class attribute", "In the instance, for example in obj.__dict__"]', 3, 'There is one descriptor for the whole class, so a value kept in it would be shared by all instances.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 3, 'Why doesn''t cached_property call the function a second time?', '["Python remembers the call arguments", "The result is stored in obj.__dict__, and a non-data descriptor is weaker than the dict", "The function is deleted after the first call", "It blocks repeated calls"]', 1, 'The lookup finds the value in the instance dictionary before it gets to the non-data descriptor.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (13, 21, 4, 'What happens on p.z = 3 if Point has __slots__ = (''x'', ''y'') and no parents with a dict?', '["A new attribute z appears", "AttributeError", "The value goes into __dict__", "The assignment is silently ignored"]', 1, 'Slots fix the set of fields and disable __dict__, so new attributes cannot be added.');
